const firebaseConfig = {
    apiKey: "AIzaSyBORppTYoq6wbsoM8cED7T_cW5UHVX5XbE",
    authDomain: "emosha-b67a3.firebaseapp.com",
    databaseURL: "https://emosha-b67a3-default-rtdb.firebaseio.com",
    projectId: "emosha-b67a3",
    storageBucket: "emosha-b67a3.firebasestorage.app",
    messagingSenderId: "136317351287",
    appId: "1:136317351287:web:f9b7186384278ba6c21d72",
    measurementId: "G-G4F8CDJV0L"
};

firebase.initializeApp(firebaseConfig);
const db = firebase.firestore();

const container = document.getElementById("linksContainer");

// جلب جميع المقالات بلا استثناء لتوليد روابطها فوراً
db.collection("articles").get().then((querySnapshot) => {
    container.innerHTML = "";

    if (querySnapshot.empty) {
        container.innerHTML = "لا توجد مقالات حالياً.";
        return;
    }

    querySnapshot.forEach((doc) => {
        const data = doc.data();
        const docId = doc.id;

        // توليد رابط مباشر للمقال يفهمه جوجل ويؤرشفه
        container.innerHTML += `${data.title}`;
    });
}).catch(err => {
    console.error("خطأ في جلب الروابط لجوجل:", err);
});
